import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, mix, color, vec2, smoothstep, length, uniform } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const {
    Group, Mesh, IcosahedronGeometry, PlaneGeometry, InstancedMesh,
    Object3D, Color, DoubleSide, AdditiveBlending, DirectionalLight,
    AmbientLight, Vector3, Box3
  } = THREE;

  const colors = config.intent?.visualSpec?.colors ?? {};
  const BG = colors.background ?? '#0b0b10';
  const INK = colors.ink ?? '#16161d';
  const SURFACE = colors.surface ?? '#101017';
  const PAPER = colors.paper ?? '#e8ecf2';
  const ACCENT = colors.accent ?? '#ff2a38';

  const cBG = new Color(BG);
  const cINK = new Color(INK);
  const cSURFACE = new Color(SURFACE);
  const cPAPER = new Color(PAPER);
  const cACCENT = new Color(ACCENT);

  const group = new Group();
  const timelines = [];
  const primHandles = [];
  const disposables = [];

  // ---------------------------------------------------------------
  // 1) STAGE — vertical gradient backdrop (BG bottom -> INK top)
  // ---------------------------------------------------------------
  {
    const geo = new PlaneGeometry(9, 7);
    const mat = new MeshBasicNodeMaterial();
    mat.colorNode = mix(color(cBG), color(cINK), uv().y);
    mat.side = DoubleSide;
    const m = new Mesh(geo, mat);
    m.position.set(0, 0, -2.5);
    group.add(m);
    disposables.push(geo, mat);
  }

  // ---------------------------------------------------------------
  // 2) LIGHTS (scene ambient 0.6 + key 1.2; node-local fill + accent rim)
  // ---------------------------------------------------------------
  const fill = new AmbientLight(cPAPER, 0.25);
  group.add(fill);
  const rim = new DirectionalLight(cACCENT, 0.8);
  rim.position.set(-3, 1.5, -4);
  group.add(rim);
  const softKey = new DirectionalLight(cPAPER, 0.6);
  softKey.position.set(3, 3, 4);
  group.add(softKey);

  // ---------------------------------------------------------------
  // 3) TEXT-CONTRAST BACKING — soft dark vignette behind hero/subhead
  //    (carves local backdrop so type reads >= 4.5:1, not glass blur)
  // ---------------------------------------------------------------
  {
    const geo = new PlaneGeometry(6.4, 2.0);
    const mat = new MeshBasicNodeMaterial();
    const p = uv().sub(vec2(0.5, 0.5));
    const d = length(vec2(p.x.mul(1.55), p.y.mul(1.0)));
    mat.colorNode = color(cBG);
    mat.opacityNode = smoothstep(0.52, 0.06, d).mul(0.66);
    mat.transparent = true;
    mat.depthWrite = false;
    mat.side = DoubleSide;
    const m = new Mesh(geo, mat);
    m.position.set(0, 0.55, 0.15);
    group.add(m);
    disposables.push(geo, mat);
  }

  // ---------------------------------------------------------------
  // 4) PARTICLE FIELD + ACCENT CORE (instanced icosahedra)
  // ---------------------------------------------------------------
  const FIELD = 1110;
  const CORE = 90;

  const fieldGeo = new IcosahedronGeometry(0.013, 0);
  const coreGeo = new IcosahedronGeometry(0.03, 0);
  disposables.push(fieldGeo, coreGeo);

  // Field: self-lit via base color * per-instance depth-graded color
  const fieldMat = new MeshBasicNodeMaterial();
  fieldMat.color = new Color(0xffffff);
  disposables.push(fieldMat);

  // Core: additive emissive accent
  const coreMat = new MeshStandardNodeMaterial();
  coreMat.color = cACCENT.clone();
  coreMat.roughness = 0.6;
  coreMat.metalness = 0.0;
  coreMat.emissive = cACCENT.clone();
  coreMat.emissiveIntensity = 1.8;
  coreMat.transparent = true;
  coreMat.depthWrite = false;
  coreMat.blending = AdditiveBlending;
  disposables.push(coreMat);

  const fieldMesh = new InstancedMesh(fieldGeo, fieldMat, FIELD);
  const coreMesh = new InstancedMesh(coreGeo, coreMat, CORE);
  disposables.push(fieldMesh, coreMesh);

  const particlesGroup = new Group();
  particlesGroup.add(fieldMesh);
  particlesGroup.add(coreMesh);
  group.add(particlesGroup);

  // ---------------------------------------------------------------
  // 5) ADDITIVE CORE GLOW — radial accent halo (depth-graded falloff)
  // ---------------------------------------------------------------
  const pulse = uniform(1.0);
  const glowGroup = new Group();
  glowGroup.position.set(0, 0, -1.5);
  particlesGroup.add(glowGroup);

  function makeHalo(radius, peak, tint) {
    const geo = new PlaneGeometry(radius * 2, radius * 2);
    const mat = new MeshBasicNodeMaterial();
    const dd = length(uv().sub(vec2(0.5, 0.5)));
    mat.colorNode = color(tint);
    mat.opacityNode = smoothstep(0.5, 0.0, dd).mul(pulse).mul(peak);
    mat.transparent = true;
    mat.depthWrite = false;
    mat.blending = AdditiveBlending;
    const m = new Mesh(geo, mat);
    disposables.push(geo, mat);
    return m;
  }
  glowGroup.add(makeHalo(0.95, 0.55, cACCENT));
  glowGroup.add(makeHalo(0.5, 0.7, cACCENT));
  glowGroup.add(makeHalo(0.22, 0.9, new Color(0xffb0b6)));

  const dummy = new Object3D();
  const tmpCol = new Color();
  const center = new Vector3(0, 0, -1.5);
  const anchors = [];
  const coreAnchors = [];

  function randInSphere() {
    let x, y, z;
    do {
      x = Math.random() * 2 - 1;
      y = Math.random() * 2 - 1;
      z = Math.random() * 2 - 1;
    } while (x * x + y * y + z * z > 1);
    return [x, y, z];
  }

  // depth falloff: 0.9 at z=0 -> 0.15 at z=-5
  function depthFactor(z) {
    let f = 0.9 + (z - 0) * ((0.15 - 0.9) / (-5 - 0));
    return Math.max(0.15, Math.min(0.9, f));
  }

  // keep front particles OUT of the type reading band (legibility)
  function inTextBand(px, py, pz) {
    return pz > -2.8 && px > -3.1 && px < 3.1 && py > -0.35 && py < 1.35;
  }

  for (let i = 0; i < FIELD; i++) {
    let px, py, pz;
    let tries = 0;
    do {
      const [x, y, z] = randInSphere();
      px = center.x + x * 3.0;
      py = center.y + y * 2.0;
      pz = center.z + z * 2.5;
      tries++;
    } while (inTextBand(px, py, pz) && tries < 12);
    const df = depthFactor(pz);
    anchors.push({
      pos: new Vector3(px, py, pz),
      phase: Math.random() * Math.PI * 2,
      freq: 0.05,
      amp: 0.04,
      dir: new Vector3(Math.random() - 0.5, Math.random() - 0.5, Math.random() - 0.5).normalize(),
      df
    });
  }

  for (let i = 0; i < CORE; i++) {
    const [x, y, z] = randInSphere();
    coreAnchors.push({
      pos: new Vector3(x * 0.5, y * 0.5, z * 0.5),
      phase: Math.random() * Math.PI * 2,
      freq: 0.05,
      amp: 0.03,
      dir: new Vector3(Math.random() - 0.5, Math.random() - 0.5, Math.random() - 0.5).normalize()
    });
  }

  function writeColors() {
    for (let i = 0; i < FIELD; i++) {
      const a = anchors[i];
      // depth-graded brightness: near = bright paper, far sinks toward BG
      tmpCol.copy(cBG).lerp(cPAPER, a.df);
      const b = 0.35 + a.df * 0.95; // extra brightness spread for depth read
      tmpCol.multiplyScalar(Math.min(1.15, b));
      fieldMesh.setColorAt(i, tmpCol);
    }
    if (fieldMesh.instanceColor) fieldMesh.instanceColor.needsUpdate = true;
  }

  function writeBase() {
    for (let i = 0; i < FIELD; i++) {
      const a = anchors[i];
      dummy.position.copy(a.pos);
      dummy.scale.setScalar(0.6 + a.df * 1.1);
      dummy.updateMatrix();
      fieldMesh.setMatrixAt(i, dummy.matrix);
    }
    fieldMesh.instanceMatrix.needsUpdate = true;
    for (let i = 0; i < CORE; i++) {
      const a = coreAnchors[i];
      dummy.position.copy(a.pos);
      dummy.scale.setScalar(1);
      dummy.updateMatrix();
      coreMesh.setMatrixAt(i, dummy.matrix);
    }
    coreMesh.instanceMatrix.needsUpdate = true;
  }
  writeColors();
  writeBase();

  // ---------------------------------------------------------------
  // 6) TEXT (MSDF) — normalized to true scene-unit heights
  // ---------------------------------------------------------------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textGroup = new Group();
  textGroup.position.z = 0.5;
  group.add(textGroup);

  const textHolders = [];

  function makeText(str, opts, targetHeight, yPos) {
    const t = ctx.fontAtlas.createText(str, opts);
    t.updateWorldMatrix(true, true);
    const box = new Box3().setFromObject(t);
    const size = box.getSize(new Vector3());
    const c = box.getCenter(new Vector3());
    let s = 1;
    if (size.y > 0 && isFinite(size.y)) s = targetHeight / size.y;
    t.scale.setScalar(s);
    t.position.set(-c.x * s, -c.y * s, 0);
    const holder = new Group();
    holder.add(t);
    holder.position.set(0, yPos, 0);
    textGroup.add(holder);
    textHolders.push(holder);
    return holder;
  }

  for (const item of items) {
    const role = item.role;
    const str = String(item.text ?? '');
    if (role === 'hero') {
      makeText(str, { fontSize: 124, color: PAPER, align: 'center', letterSpacingPx: -1 }, 0.62, 0.95);
    } else if (role === 'subhead') {
      makeText(str, { fontSize: 40, color: PAPER, align: 'center', letterSpacingPx: 1 }, 0.19, 0.28);
    } else {
      makeText(str, { fontSize: 18, color: ACCENT, align: 'center', letterSpacingPx: 3 }, 0.09, -2.1);
    }
  }

  // ---------------------------------------------------------------
  // 7) CINEMATIC PRIMITIVES (particle-emerge on the particle group)
  // ---------------------------------------------------------------
  for (const prim of (config.cinematicPrimitives ?? [])) {
    const fn = ctx.primitives?.[prim.name];
    if (fn) {
      try {
        const h = fn(particlesGroup, prim.params ?? {});
        if (h) primHandles.push(h);
      } catch (e) { /* ignore */ }
    }
  }

  // ---------------------------------------------------------------
  // 8) ENTRANCE MOTION — field emerge + weighted-settle text
  // ---------------------------------------------------------------
  particlesGroup.scale.setScalar(0.001);
  const fieldTl = gsap.timeline();
  fieldTl.to(particlesGroup.scale, {
    x: 1, y: 1, z: 1, duration: 1.4, ease: 'power3.out'
  });
  timelines.push(fieldTl);

  textHolders.forEach((h, idx) => {
    const baseY = h.position.y;
    const tl = gsap.timeline({ delay: 0.5 + idx * 0.08 });
    tl.fromTo(h.position, { y: baseY + 0.4 }, { y: baseY, duration: 0.7, ease: 'power3.out' });
    tl.fromTo(h.scale, { x: 1.04, y: 1.04, z: 1.04 }, { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' }, 0);
    timelines.push(tl);
  });

  // ---------------------------------------------------------------
  // 9) IDLE DRIFT + CORE PULSE (single slow transform per element)
  // ---------------------------------------------------------------
  let rafActive = true;
  const startT = performance.now();
  let rafId = 0;

  function tick() {
    if (!rafActive) return;
    const elapsed = (performance.now() - startT) / 1000;

    for (let i = 0; i < FIELD; i++) {
      const a = anchors[i];
      const off = Math.sin(elapsed * a.freq * Math.PI * 2 + a.phase) * a.amp;
      dummy.position.copy(a.pos).addScaledVector(a.dir, off);
      dummy.scale.setScalar(0.6 + a.df * 1.1);
      dummy.updateMatrix();
      fieldMesh.setMatrixAt(i, dummy.matrix);
    }
    fieldMesh.instanceMatrix.needsUpdate = true;

    for (let i = 0; i < CORE; i++) {
      const a = coreAnchors[i];
      const off = Math.sin(elapsed * a.freq * Math.PI * 2 + a.phase) * a.amp;
      dummy.position.copy(a.pos).addScaledVector(a.dir, off);
      dummy.scale.setScalar(1);
      dummy.updateMatrix();
      coreMesh.setMatrixAt(i, dummy.matrix);
    }
    coreMesh.instanceMatrix.needsUpdate = true;

    const pulseV = 0.85 + Math.sin(elapsed * 0.1 * Math.PI * 2) * 0.15;
    coreMat.emissiveIntensity = 1.65 + Math.sin(elapsed * 0.1 * Math.PI * 2) * 0.15;
    pulse.value = pulseV;

    rafId = requestAnimationFrame(tick);
  }
  rafId = requestAnimationFrame(tick);

  // ---------------------------------------------------------------
  group.userData.handlers = {};
  group.userData.cleanup = () => {
    rafActive = false;
    if (rafId) cancelAnimationFrame(rafId);
    for (const tl of timelines) { try { tl.kill(); } catch (e) {} }
    for (const h of primHandles) { try { h.cleanup?.(); } catch (e) {} }
    for (const d of disposables) { try { d.dispose?.(); } catch (e) {} }
    textGroup.traverse((o) => {
      if (o.geometry) o.geometry.dispose?.();
      if (o.material) {
        if (Array.isArray(o.material)) o.material.forEach((m) => m.dispose?.());
        else o.material.dispose?.();
      }
    });
  };

  return group;
}
